<script lang="ts">
 import {onMount} from 'svelte';import {api} from '../lib/api.js';import type {WorkbenchState} from '../lib/workbench-state.js';import ChevronRight from '@lucide/svelte/icons/chevron-right';import CircleAlert from '@lucide/svelte/icons/circle-alert';import Database from '@lucide/svelte/icons/database';import FileCode from '@lucide/svelte/icons/file-code';import Network from '@lucide/svelte/icons/network';import ShieldCheck from '@lucide/svelte/icons/shield-check';
 export let state:WorkbenchState;let selection:any,running=false,result:any,args='[]',contextId='local',semantic:any,loading=false,error='',generation=0,correctionKind:'rename'|'purpose'|'group'|'ignore'|'split'|'merge'='rename',correctionValue='',correctionLabel='',correcting=false,correctionError='';
 const icon=(kind:string)=>kind==='database'?Database:kind==='module'||kind==='function'?FileCode:kind==='identity'?ShieldCheck:Network;
 const related=(id:string)=>semantic?.relatedEntities?.find((value:any)=>value.id===id);
 const safeEntries=(value:any)=>Object.entries(value??{}).filter(([,item])=>item!==undefined&&item!==null&&typeof item!=='object').slice(0,30);
 const sections=()=>semantic?.views?.[0]?.sections??[{kind:'properties',title:'Identity'},{kind:'relationships',title:'Relationships'},{kind:'evidence',title:'Why Atlas believes this'},{kind:'timeline',title:'Recent changes'}];
 const sectionEntries=(descriptor:any)=>{const entries=safeEntries(semantic?.entity?.attributes);return descriptor.fields?.length?entries.filter(([key])=>descriptor.fields.includes(key)):entries};
 const sectionAssertions=(descriptor:any)=>descriptor.predicate?semantic.assertions.filter((value:any)=>value.predicate===descriptor.predicate):semantic.assertions;
 async function loadSemantic(){const token=++generation;if(!selection?.semantic){semantic=undefined;return}loading=true;error='';try{const [detail,timeline]=await Promise.all([api<any>(`/api/world/entities/${encodeURIComponent(selection.id)}?contextId=${encodeURIComponent(selection.contextId??contextId)}`),api<any>(`/api/world/entities/${encodeURIComponent(selection.id)}/timeline?contextId=${encodeURIComponent(selection.contextId??contextId)}`)]);if(token===generation)semantic={...detail,timeline:timeline.items}}catch(value){if(token===generation)error=(value as Error).message}finally{if(token===generation)loading=false}}
 async function run(){if(!selection?.id||running)return;running=true;try{const symbolId=semantic?.entity?.attributes?.legacyId??selection.id;result=await api<any>('/api/run',{method:'POST',body:JSON.stringify({contextId:selection.contextId??contextId,symbolId,args:JSON.parse(args),consent:true})})}catch(value){result={classification:'unavailable',error:(value as Error).message}}finally{running=false}}
 async function correct(){if(!semantic?.entity||correcting)return;correcting=true;correctionError='';try{const id=semantic.entity.id,value=correctionKind==='ignore'?true:correctionKind==='split'?{memberIds:correctionValue.split(',').map(item=>item.trim()).filter(Boolean),label:correctionLabel.trim()}:correctionValue.trim();await api(`/api/world/entities/${encodeURIComponent(id)}/correction`,{method:'PUT',body:JSON.stringify({contextId:semantic.entity.contextId,kind:correctionKind,value,confirm:true})});await loadSemantic();window.dispatchEvent(new Event('atlas:graph-refresh'));correctionValue='';correctionLabel=''}catch(value){correctionError=(value as Error).message}finally{correcting=false}}
 async function resetCorrections(){if(!semantic?.entity||correcting)return;correcting=true;correctionError='';try{await api(`/api/world/entities/${encodeURIComponent(semantic.entity.id)}/correction`,{method:'DELETE',body:JSON.stringify({contextId:semantic.entity.contextId,confirm:true})});await loadSemantic();window.dispatchEvent(new Event('atlas:graph-refresh'))}catch(value){correctionError=(value as Error).message}finally{correcting=false}}
 function choose(entity:any){state.select({id:entity.id,type:entity.kind,contextId:entity.contextId,label:entity.label,semantic:true})}
 onMount(()=>state.subscribe(value=>{selection=value.selection;contextId=value.contextId;result=undefined;void loadSemantic()}));
</script>
<section class="panel details-panel semantic-details"><header><strong>Inspector</strong><button title="Ask Atlas Agent about the selected item" onclick={()=>{if(selection)window.dispatchEvent(new CustomEvent('atlas:agent-chat-reference',{detail:{kind:'device',id:selection.id,label:selection.label??selection.id}}));window.dispatchEvent(new Event('atlas:open-agent-chat'))}}>Ask Agent</button>{#if (semantic?.entity?.kind??selection?.type)==='function'}<button onclick={run} disabled={running} title="Run this function in the Atlas sandbox">{running?'Running…':'Run function'}</button>{/if}</header>
{#if loading}<div class="empty-copy">Resolving semantic evidence…</div>{:else if error}<div class="panel-error">{error}</div>{:else if semantic?.entity}
 {@const entity=semantic.entity}{@const KindIcon=icon(entity.kind)}
 <div class="entity-head"><KindIcon size={22}/><div><small>{entity.kind} · {entity.namespace}</small><h2>{entity.label}</h2></div><span class:stale={entity.stale}>{entity.stale?'stale':'current'}</span></div>
 <details class="correct-atlas"><summary>Correct Atlas {#if semantic.corrections?.length}<small>· User-defined</small>{/if}</summary><p>Corrections change Atlas’s presentation, not the observations or interpreter evidence below.</p><label>Correction<select bind:value={correctionKind}><option value="rename">Rename</option><option value="purpose">Describe purpose</option><option value="group">Move region</option><option value="ignore">Ignore this entity</option>{#if entity.kind==='workload'}<option value="split">Split selected member IDs</option><option value="merge">Merge into workload ID</option>{/if}</select></label>{#if correctionKind==='group'}<select bind:value={correctionValue} aria-label="Destination region"><option value="">Choose a region</option><option value="applications">Applications</option><option value="data">Data</option><option value="infrastructure">Infrastructure</option><option value="development">Development</option><option value="system">System</option><option value="external">External</option></select>{:else if correctionKind==='split'}<input bind:value={correctionValue} placeholder="Comma-separated member entity IDs" aria-label="Member entity IDs"/><input bind:value={correctionLabel} placeholder="New workload name" aria-label="New workload name"/>{:else if correctionKind!=='ignore'}<input bind:value={correctionValue} placeholder={correctionKind==='merge'?'Target workload ID':'Your correction'} aria-label="Correction value"/>{/if}<div class="correction-actions"><button disabled={correcting} onclick={correct}>Apply correction</button>{#if semantic.corrections?.length}<button disabled={correcting} onclick={resetCorrections}>Reset corrections</button>{/if}</div>{#if correctionError}<p class="panel-error">{correctionError}</p>{/if}{#if semantic.corrections?.length}<small>User-defined: {semantic.corrections.map((item:any)=>item.kind).join(', ')}</small>{/if}</details>
 {#if entity.kind==='function'}<label class="args-field">Arguments (JSON)<input bind:value={args} aria-label="Function arguments"/></label>{/if}{#if result}<pre class="operation-result">{JSON.stringify(result,null,2)}</pre>{/if}
 {#each sections() as descriptor}
  <section><h3>{descriptor.title??descriptor.kind}</h3>
  {#if descriptor.kind==='properties'||descriptor.kind==='metrics'||descriptor.kind==='documentation'}<dl>{#each sectionEntries(descriptor) as [key,value]}<dt>{key}</dt><dd>{String(value)}</dd>{:else}<p>{descriptor.empty??'No matching properties.'}</p>{/each}</dl>
  {:else if descriptor.kind==='relationships'}<div class="relations">{#each sectionAssertions(descriptor) as assertion}{@const other=related(assertion.subjectId===entity.id?assertion.objectId:assertion.subjectId)}<button onclick={()=>other&&choose(other)} disabled={!other}><span><b>{assertion.predicate.replaceAll('-',' ')}</b><small>{assertion.classification} · {Math.round(assertion.confidence*100)}%</small></span><ChevronRight size={13}/><em>{other?.label??String(assertion.value??'evidence')}</em></button>{:else}<p>{descriptor.empty??'No semantic relationships yet.'}</p>{/each}</div>
  {:else if descriptor.kind==='evidence'}{#each sectionAssertions(descriptor) as assertion}<article class="evidence"><div><span class:inferred={assertion.classification==='inferred'}>{assertion.classification}</span><b>{assertion.predicate.replaceAll('-',' ')}</b><small>{assertion.interpreterId}@{assertion.interpreterVersion}</small></div><p>{assertion.explanation}</p><footer>{assertion.evidence.length} evidence reference{assertion.evidence.length===1?'':'s'} · {Math.round(assertion.confidence*100)}% confidence</footer></article>{:else}<p>{descriptor.empty??'No assertions support this entity yet.'}</p>{/each}
  {:else if descriptor.kind==='timeline'}{#each (semantic.timeline??[]).slice(0,12) as item}<div class="timeline"><i></i><span><b>{item.changeType}</b><small>{item.interpreterId} · {new Date(item.changedAt).toLocaleString()}</small></span></div>{:else}<p>{descriptor.empty??'No retained changes.'}</p>{/each}
  {:else if descriptor.kind==='hierarchy'}<div class="relations">{#if entity.parentId&&related(entity.parentId)}{@const parent=related(entity.parentId)}<button onclick={()=>choose(parent)}><span><b>parent</b><small>{parent.kind}</small></span><ChevronRight size={13}/><em>{parent.label}</em></button>{:else}<p>{descriptor.empty??'No parent relationship.'}</p>{/if}</div>{/if}
  </section>
 {/each}
{:else if selection}<div class="detail-title">{selection.label??selection.name??selection.id}</div><dl>{#each Object.entries(selection) as [key,value]}<dt>{key}</dt><dd>{typeof value==='object'?JSON.stringify(value):String(value)}</dd>{/each}</dl>{:else}<div class="empty-copy"><CircleAlert size={24}/>Select a workload, capability, process, module, or function to inspect why Atlas believes it exists.</div>{/if}</section>
<style>
 .semantic-details{overflow:auto}.entity-head{display:flex;align-items:center;gap:9px;padding:12px;border-bottom:1px solid #26323e}.entity-head>:global(svg){color:#62d9cc}.entity-head div{min-width:0;flex:1}.entity-head small{color:#748496;font-size:9px;text-transform:uppercase}.entity-head h2{overflow:hidden;margin:2px 0 0;color:#edf4fa;font-size:14px;text-overflow:ellipsis;white-space:nowrap}.entity-head>span{border-radius:10px;background:#233727;padding:3px 7px;color:#9ee6a8;font-size:9px}.entity-head>span.stale{background:#3f2424;color:#ff9b9b}.semantic-details section{padding:10px 12px;border-bottom:1px solid #202b35}.semantic-details h3{margin:0 0 8px;color:#8999a9;font-size:9px;letter-spacing:.08em;text-transform:uppercase}.semantic-details p{margin:6px 0;color:#768594;font-size:10px}.relations{display:grid;gap:4px}.relations button{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;gap:5px;border:1px solid #273440;border-radius:5px;background:#101820;padding:6px;text-align:left}.relations button:hover:not(:disabled){border-color:#4c667b}.relations button:disabled{opacity:.75}.relations span{display:grid}.relations b{color:#c9d5df;font-size:10px}.relations small,.relations em{overflow:hidden;color:#718191;font-size:9px;font-style:normal;text-overflow:ellipsis;white-space:nowrap}.evidence{margin:6px 0;border:1px solid #273440;border-radius:6px;background:#0c1319;padding:7px}.evidence>div{display:flex;align-items:center;gap:6px}.evidence span{border-radius:8px;background:#24392c;padding:2px 5px;color:#9bd7a8;font-size:8px;text-transform:uppercase}.evidence span.inferred{background:#3d3220;color:#f3cc76}.evidence b{color:#d3dee7;font-size:10px}.evidence small{margin-left:auto;color:#667585;font-size:8px}.evidence footer{color:#697988;font-size:8px}.timeline{display:flex;align-items:center;gap:7px;padding:4px 0}.timeline i{width:6px;height:6px;border-radius:50%;background:#62d9cc}.timeline span{display:grid}.timeline b{font-size:10px}.timeline small{color:#697988;font-size:8px}.empty-copy{gap:8px}
 .correct-atlas{padding:10px 12px;border-bottom:1px solid #26323e}.correct-atlas summary{cursor:pointer;color:#b7c9d5;font-size:10px}.correct-atlas label{display:grid;gap:4px;color:#8999a9;font-size:9px}.correct-atlas input,.correct-atlas select{width:100%;margin:4px 0;border:1px solid #334454;border-radius:4px;background:#101820;padding:6px;color:#e4eef5;font-size:10px}.correction-actions{display:flex;gap:6px}.correction-actions button{border:1px solid #39516a;border-radius:4px;background:#172733;padding:5px 7px;color:#d8e5ee;font-size:10px}
</style>
